const PRESET_MANAGER_BUTTON_NAME = '预设缝合';
let presetManagerLoadPromise;

async function getLatestVersion() {
  try {
    const response = await fetch('https://api.github.com/repos/jerryzmtz/tauritavern-preset-manager/tags');
    const tags = await response.json();
    return tags[0]?.name || 'main';
  } catch {
    return 'main';
  }
}

async function loadPresetManager() {
  if (window.__TT_PRESET_STITCHER_OPEN__) {
    return;
  }
  presetManagerLoadPromise ??= (async () => {
    const version = await getLatestVersion();
    await import(`https://testingcf.jsdelivr.net/gh/jerryzmtz/tauritavern-preset-manager@${version}/dist/preset-manager/index.js`);
  })();
  await presetManagerLoadPromise;
}

$(() => {
  replaceScriptButtons([{ name: PRESET_MANAGER_BUTTON_NAME, visible: true }]);
  eventOn(getButtonEvent(PRESET_MANAGER_BUTTON_NAME), async () => {
    try {
      await loadPresetManager();
      window.__TT_PRESET_STITCHER_OPEN__?.();
    } catch (error) {
      console.error('预设缝合管理器加载失败', error);
      toastr?.error?.('预设缝合管理器加载失败，请检查网络或稍后重试');
    }
  });
});
